// Input from assistant-core arrives as JSON in the webhook body.
// Do your work here (call an API node instead of Code for real integrations),
// then return a small JSON result the LLM can read. Always include `ok`.
const d = $json.body || $json || {};
try {
  // ...do something with d.<your fields>...
  return [{ json: { ok: true, echo: d } }];
} catch (e) {
  return [{ json: { ok: false, error: e.message } }];
}
